// HG-2 watchdog. Reads what WF06 wrote (HeyGen_Submitted_At, HeyGen_ID_History) and decides whether to alert.
const STALE_MIN = 20;
const WPM = 150;                 // speaking rate used to estimate video length from the script
const COST_PER_MIN_USD = 6;      // assumed HeyGen API rate per minute of video. Estimate only; change here if the real rate differs.
const TABLE = 'tblSBKG2Zx2nZUPIT';
const N8N = 'https://marketing.alfredai.bot/workflow/';
const NL = String.fromCharCode(10);
const SEP = '==============================';
const TAG = 'AVATAR (WF06)';
const clients = $('1. Load Clients').all().map(i => i.json);
const sel = v => (v && typeof v === 'object') ? (v.name || '') : (v || '');
const dayOf = (iso, tz) => { const d = DateTime.fromISO(String(iso || '')); return d.isValid ? d.setZone(tz).toFormat('yyyy-MM-dd') : ''; };
const stripBlock = notes => { const head = SEP + NL + TAG; let s = String(notes || ''); let i = s.indexOf(head); while (i >= 0) { const j = s.indexOf(NL + SEP + NL, i + head.length); s = s.slice(0, i).trimEnd() + (j >= 0 ? s.slice(j) : ''); i = s.indexOf(head); } return s.trim(); };
const estSecs = script => { const w = String(script || '').split(' ').filter(x => x.trim().length > 0).length; return w > 0 ? Math.round(w / WPM * 60) : 0; };
const usd = secs => '$' + (secs / 60 * COST_PER_MIN_USD).toFixed(2);
const mmss = sec => Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0');
const recUrl = (baseId, id) => 'https://airtable.com/' + baseId + '/' + TABLE + '/' + id;
const hgUrl = id => 'https://app.heygen.com/videos/' + id;

// Rows arrive from the client loop, each stamped with _client by 2b.
const by = {};
for (const it of $input.all()) { const j = it.json || {}; const k = j._client || ''; (by[k] = by[k] || []).push(j); }

const store = $getWorkflowStaticData('global');
store.sent = store.sent || {};
const cutoff = DateTime.now().minus({ days: 3 }).toFormat('yyyy-MM-dd');
for (const key of Object.keys(store.sent)) { if (key.slice(0, 10) < cutoff) delete store.sent[key]; }
const fresh = (key, value) => { if (store.sent[key] === value) return false; store.sent[key] = value; return true; };

const sections = [];
const table = [];
const stale = [];
let capTotal = 0;
let submitTotal = 0;
let extraSecsTotal = 0;

clients.forEach((c, k) => {
  const name = c.Client_Name || ('client ' + k);
  const tz = c.Timezone || 'Asia/Manila';
  const baseId = c.Video_Base_ID || '';
  const cap = (typeof c.Daily_Video_Cap === 'number' && c.Daily_Video_Cap >= 0) ? Math.floor(c.Daily_Video_Cap) : 3;
  const today = DateTime.now().setZone(tz).toFormat('yyyy-MM-dd');
  const rows = by[name] || [];
  const out = [];
  const err = rows.find(r => r && r.error);
  if (err) {
    const msg = String((err.error && err.error.message) || err.error).substring(0, 200);
    table.push(name + ': could not be read');
    if (fresh(today + '|' + name + '|readerror', msg)) {
      out.push(['PROBLEM: this brand cannot be read', 'What it means: the watchdog could not open the Reel Engine table, so this brand is not being watched. WF06 Global also submits nothing for it.', 'What to do: check that the base has the fields HeyGen_Submitted_At and HeyGen_ID_History and that the Airtable token can open it.', 'Error: ' + msg, 'Base: https://airtable.com/' + baseId].join(NL + '  '));
    }
  } else {
    let submits = 0;
    let secsToday = 0;
    let reelsToday = 0;
    for (const r of rows) {
      if (!r || !r.id) continue;
      const status = String(sel(r.Status));
      const vid = String(r.HeyGen_Video_ID || '').trim();
      const topic = r.Topic || r.id;
      const secs = estSecs(r.Script);
      const hist = String(r.HeyGen_ID_History || '').split(NL).map(l => l.trim()).filter(Boolean);
      const histToday = hist.filter(l => dayOf(l.split('|')[0].trim(), tz) === today).length;
      const submittedToday = dayOf(r.HeyGen_Submitted_At, tz) === today;
      if (submittedToday) { const n = Math.max(histToday, (vid || status === 'Video Processing') ? 1 : 0); submits += n; if (n > 0) { secsToday += secs * n; reelsToday += n; } }
      if (hist.length >= 2 && histToday >= 1 && fresh(today + '|' + name + '|double|' + r.id, hist.length)) {
        const extra = hist.length - 1;
        extraSecsTotal += secs * extra;
        const idLines = hist.map(l => { const p = l.split('|'); const id = (p[1] || '').trim(); return '    ' + (p[0] || '').trim() + '  ' + id + (id ? '  ' + hgUrl(id) : ''); });
        out.push(['PROBLEM: a reel was rendered more than once', 'Reel: ' + topic, 'Record: ' + recUrl(baseId, r.id), 'HeyGen renders (' + hist.length + '):'].join(NL + '  ') + NL + idLines.join(NL) + NL + '  ' + ['Estimated cost of the extra ' + extra + ' render(s): ' + (secs > 0 ? usd(secs * extra) + ' (about ' + mmss(secs) + ' each)' : 'unknown, the record has no script'), 'What it means: this is the 29 Sep bug pattern, or someone cleared HeyGen_Video_ID and sent the reel again by hand.', 'What to do: open the record. If nobody re-sent it on purpose, unpublish WF06 and raise it. Keep one render, ignore the rest.'].join(NL + '  '));
      }
      if (status === 'Video Processing' && !vid) {
        const at = DateTime.fromISO(String(r.HeyGen_Submitted_At || ''));
        const ageMin = at.isValid ? Math.round((Date.now() - at.toMillis()) / 60000) : null;
        if (ageMin === null || ageMin >= STALE_MIN) {
          const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
          const block = [SEP, TAG, 'Updated: ' + stamp, 'Stage: Error - locked with no HeyGen ID', 'Detail: The record was locked for HeyGen but no video ID was written' + (ageMin === null ? '' : ' after ' + ageMin + ' minutes') + '. Check HeyGen for a render of this reel before setting Status back to Ready for Video Generation.'].join(NL);
          const base = stripBlock(r.Reel_Notes);
          stale.push({ base_id: baseId, record_id: r.id, reel_notes_final: (base ? base + NL + NL : '') + block });
          out.push(['PROBLEM: a reel got stuck and was set to Failed', 'Reel: ' + topic, 'Record: ' + recUrl(baseId, r.id), 'Locked: ' + (ageMin === null ? 'time unknown' : ageMin + ' minutes ago') + ', no HeyGen ID was written', 'Possible cost: ' + (secs > 0 ? 'up to ' + usd(secs) + ' if HeyGen did render it' : 'unknown, the record has no script'), 'What it means: the run stopped between locking the reel and saving the HeyGen ID. HeyGen may hold a paid render that was never collected.', 'What to do: look for this reel in HeyGen (https://app.heygen.com). If it is there, paste its ID into HeyGen_Video_ID and set Status to Video Processing. If not, set Status back to Ready for Video Generation.'].join(NL + '  '));
        }
      }
    }
    capTotal += cap;
    submitTotal += submits;
    table.push(name + ': ' + submits + ' of ' + cap + (submits > cap ? '  OVER CAP' : ''));
    if (submits > cap && fresh(today + '|' + name + '|overcap', submits)) {
      const over = submits - cap;
      const avg = reelsToday > 0 ? Math.round(secsToday / reelsToday) : 0;
      extraSecsTotal += avg * over;
      out.push(['PROBLEM: over the daily cap', 'Submits today: ' + submits + ', cap is ' + cap + ' (' + over + ' over)', 'Estimated cost of the ' + over + ' extra render(s): ' + (avg > 0 ? usd(avg * over) + ' (about ' + mmss(avg) + ' each)' : 'unknown'), 'What it means: the cap in WF06 was bypassed. Either two runs overlapped, or videos were sent to HeyGen outside WF06.', 'What to do: check which reels were sent today in the base. If it keeps climbing, unpublish WF06 and raise it.', 'Base: https://airtable.com/' + baseId + '/' + TABLE].join(NL + '  '));
    }
  }
  if (out.length) sections.push(name + NL + out.map(l => '- ' + l).join(NL + NL));
});

const send = sections.length > 0;
const subject = 'HeyGen alert: ' + submitTotal + ' submits today against a cap total of ' + capTotal;
const body = send ? [
  'HeyGen spend watchdog (WF06w). Something needs a look.',
  '',
  sections.join(NL + NL),
  '',
  'TODAY, ALL BRANDS (submits of daily cap)',
  table.map(l => '  ' + l).join(NL),
  '  Total: ' + submitTotal + ' of ' + capTotal,
  '',
  'ESTIMATED EXTRA COST IN THIS ALERT: ' + (extraSecsTotal > 0 ? usd(extraSecsTotal) : '$0.00') + '  (script length at ' + WPM + ' words per minute, assumed $' + COST_PER_MIN_USD + ' per minute of video; an estimate, not the HeyGen bill)',
  '',
  'LINKS',
  '  WF06 AlfredAI: ' + N8N + 'wnsZb16pGKHeVLIg',
  '  WF06 Global: ' + N8N + 'rXq5PGyeHbA0oatk',
  '  This watchdog: ' + N8N + '22elUM8m8rNHaJAy',
  '  HeyGen: https://app.heygen.com',
  '',
  'Each problem is emailed once per day unless its count goes up. No email means nothing is wrong.'
].join(NL) : '';
return [{ json: { send, subject, body, stale, submit_total: submitTotal, cap_total: capTotal } }];

const c = $('1b. Client Loop').first(1).json;
const rows = $input.all().map(i => i.json || {});
const out = rows.filter(r => r.id || r.error).map(r => ({ json: { ...r, _client: c.Client_Name } }));
if (!out.length) out.push({ json: { _client: c.Client_Name, _empty: true } });
return out;
